    lines: [{ sku: 'DES-HOUR', qty: 5.5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with different quantities', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 8500 }), 850000);
});

test('lineTotal works with different unit prices', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 100 }), 500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 1 }), 5);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
});

test('invoiceTotals returns total equal to subtotal when no discount or VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals handles multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 },
      { sku: 'TALK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const expected = 60000 + 35000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine copies product details from catalogue', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 2 });
  const line = result.value.lines[1];
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('addLine validates qty like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: 5.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(invoice.value, { sku: 'NOPE', qty: 3 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
